const WORD = { work: 'work', ask: 'ask', success: 'happy', error: 'sad' };
const FLOW = new Set(['work', 'ask']);
const TERMINAL = new Set(['success', 'error']);

/** Apply Matter lifecycle inside the existing sandbox, leaving finite figure animations intact. */
export function withMatterActivity(body) {
  let desired = { kind: 'idle' }, playing = null, stationary = false, applied = false, disposed = false;
  const completed = new Set();
  const wanted = () => TERMINAL.has(desired.kind) && completed.has(desired.id) ? 'idle' : desired.kind;
  const locked = () => !!playing || wanted() !== 'idle';
  function syncStationary() {
    const next = stationary || locked();
    if (next !== applied) { applied = next; body.set?.({ stationary: next }); }
  }
  function inAnimation(layout) {
    return layout.work || layout.ask || layout.gesture || layout.expression && layout.expression !== 'neutral';
  }
  function running(layout) {
    return FLOW.has(playing.word) ? layout[playing.word] || layout.gesture === playing.word
      : layout.expression === playing.word || layout.gesture === playing.word;
  }
  function finish() {
    if (TERMINAL.has(playing.kind)) {
      completed.add(playing.id);
      if (completed.size > 32) completed.delete(completed.values().next().value);
    }
    playing = null;
  }
  const overrides = {
    set(state) {
      const { matterActivity, stationary: external, ...rest } = state;
      if ('matterActivity' in state) {
        const kind = matterActivity?.kind;
        desired = Object.hasOwn(WORD, kind) ? { kind, id: matterActivity.id } : { kind: 'idle' };
        if (TERMINAL.has(kind) && (!desired.id || matterActivity.expiresAt <= Date.now())) desired = { kind: 'idle' };
      }
      if (typeof external === 'boolean') stationary = external;
      body.set?.(rest);
      syncStationary();
    },
    step(dt) {
      if (disposed) return;
      syncStationary();
      body.step(dt);
      if (!(dt > 0 && Number.isFinite(dt))) return;
      let layout = body.layout();
      if (playing && !running(layout)) finish();
      const kind = wanted();
      if (!playing && kind !== 'idle' && !layout.busy && !layout.pressing) {
        // Sleeping/seated bodies need waking; all finite motions and landing modes finish first.
        if (['sit', 'sleep'].includes(layout.mode)) body.do('stand');
        // A pack's work/ask pulse may outlive a drag-cleared flow. Do not wait for that stale pulse.
        const animation = inAnimation({ ...layout,
          gesture: FLOW.has(layout.gesture) && !layout.work && !layout.ask ? null : layout.gesture });
        if (layout.mode === 'idle' && !animation) {
          const word = WORD[kind];
          if (body.do(word) !== false) playing = { kind, word, id: desired.id };
        }
      }
      syncStationary();
    },
    do(word) { return locked() ? false : body.do(word); },
    layout() { return { ...body.layout(), matterActivity: playing?.kind ?? (wanted() === 'idle' ? null : wanted()) }; },
    dispose() { disposed = true; playing = null; desired = { kind: 'idle' }; return body.dispose?.(); },
  };
  if (body.pointer) overrides.pointer = (type, point) => {
    const result = body.pointer(type, point);
    if (type === 'down' && body.layout().pressing) playing = null;
    return result;
  };
  if (body.drop) overrides.drop = (point) => { playing = null; return body.drop(point); };
  for (const key of ['walk', 'move', 'cue']) if (body[key]) {
    overrides[key] = (...args) => locked() ? false : body[key](...args);
  }
  const bound = new Map();
  return new Proxy(body, {
    get(target, key) {
      if (Object.hasOwn(overrides, key)) return overrides[key];
      const value = Reflect.get(target, key, target);
      if (typeof value !== 'function') return value;
      if (!bound.has(key)) bound.set(key, value.bind(target));
      return bound.get(key);
    },
  });
}
